const int N = 3e5 + 10;
ll a[N];
ll pref[N];
ll dp1[N], dp2[N];
void solve() {
	int n, m, v;
	cin >> n >> m >> v;
	for (int i = 0; i <= n + 2; i++) {
		dp1[i] = 0;
		dp2[i] = 0;
	}
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
		pref[i] = pref[i - 1] + a[i];
	}
	for (int i = 1; i <= n; i++) {
		int l = 1, r = i, ans = -1;
		while (l <= r) {
			int mid = (l + r) / 2;
			if ((pref[i] - pref[mid - 1]) >= v) {
				ans = mid;
				l = mid + 1;
			}
			else r = mid - 1;
		}
		if (ans == -1) dp1[i] = 0;
		else dp1[i] = dp1[ans - 1] + 1;
	}
	for (int i = n; i >= 1; i--) {
		int l = i, r = n, ans = -1;
		while (l <= r) {
			int mid = (l + r) / 2;
			if ((pref[mid] - pref[i - 1]) >= v) {
				ans = mid;
				r = mid - 1;
			}
			else l = mid + 1;
		}
		if (ans == -1) dp2[i] = 0;
		else dp2[i] = dp2[ans + 1] + 1;
	}
	ll answ = -1;
	for (int i = 1; i <= n; i++) {
		if (dp2[i] == m) {
			answ = max(answ, pref[i - 1]);
		}
	}
	for (int i = 1; i <= n; i++) {
		if (dp1[i] == m) {
			answ = max(answ, pref[n] - pref[i]);
			continue;
		}
		int l = i + 1, r = n, ans = -1;
		while (l <= r) {
			int mid = (l + r) / 2;
			if (dp2[mid] >= (m - dp1[i])) {
				ans = mid;
				l = mid + 1;
			}
			else r = mid - 1;
		}
		if (ans == -1) continue;
		answ = max(answ, pref[ans - 1] - pref[i]);
	}
	cout << answ << "\n";
}
int main() {
	int t;
	cin >> t;
	while (t--) {
		solve();
	}
}

#include <iostream>

#include <set>

#include <algorithm>

using namespace std;



typedef pair<int, int> pii;

const int N = 2 * 100 * 1000 +10;



pii seg[N];

int dp_last, dp, big, cmp;



void Solve()

{

    int n; cin>>n;

    for(int i=1; i<=n; i++)

        cin>>seg[i].first>>seg[i].second;

    sort(seg+1, seg+n+1);



    /// Base

    set<pii> s;

    s.insert({seg[1].second, 1});

    cmp = big = 1;

    dp = -1;

    dp_last = 0;



    /// Solve

    for(int i=2; i<=n; i++)

    {

        if(seg[i].second <= seg[big].second)

        {

            if(i == 2)

                dp = 1;

            s.erase({seg[big].second, big});

            dp_last += (s.empty() || s.rbegin() -> first < seg[i].first);

            s.insert({seg[big].second, big});

        }

        else if(seg[big].second < seg[i].first)

        {

            dp = max(dp, dp_last) + 1;

            dp_last = cmp ++;

            big = i;

        }

        else

        {

            /// DP LAST

            int new_dp_last = cmp;



            /// DP

            int dp1 = dp, dp2 = dp_last;

            s.erase({seg[big].second, big});

            dp2 += (s.empty() || s.rbegin() -> first < seg[i].first);

            s.insert({seg[big].second, big});



            /// UPD

            dp_last = new_dp_last;

            dp = max(dp1, dp2);

            big = i;

        }

        s.insert({seg[i].second, i});

    }

    cout<<max(dp, dp_last)<<'\n';

}



int main()

{

    ios_base::sync_with_stdio(false); cin.tie(0); cout.tie(0);

    int t; cin>>t;

    while(t --)

        Solve();

    return 0;

}

