def Solucion(n,k,c,f,h):
    h = [0]+h

    count_fav = {}
    max_count_fav = 0
    for i in f:
        if i in count_fav:
            count_fav[i] += 1
            if max_count_fav < count_fav[i]:
                max_count_fav = count_fav[i]
        else:
            count_fav[i] = 1

    count_num = {}
    max_count_num = 0
    for i in c:
        if i in f:
            if i in count_num:
                count_num[i] += 1
                if max_count_num < count_num[i]:
                    max_count_num = count_num[i]
            else:
                count_num[i] = 1
    max_count_num = min(max_count_num, k)


    dp = [[0]*(max_count_fav*max_count_num+1) for _ in range(max_count_fav+1)]
    for jugador in range(max_count_fav):
        for card in range(max_count_fav*max_count_num):
            for repartidas in range(max_count_num+1):
                if card+repartidas > max_count_fav*max_count_num:
                    continue
                dp[jugador+1][card+repartidas] = max(dp[jugador+1][card+repartidas], dp[jugador][card] + h[repartidas])


    joy = 0
    for i in count_num:
        joy += dp[count_fav[i]][count_num[i]]

    return joy

