void dfs(int v, int p, vector<int> &vis , vector<int> &leaf, vector<int> &path, vector<vector<int>> &store, vector<int> adj[]) {

	if (!vis[v]) {

		path.pb(v);

		vis[v] = 1;

	}

	if (leaf[v]) {

		store.pb(path);

		path.clear();

		return;

	}

	for (auto &u : adj[v]) {

		if (u != p) {

			dfs(u, v, vis, leaf, path, store, adj);

		}

	}

}



void solve() {

	int n, root;

	cin >> n;

	vector<int> adj[n + 1], leaf(n + 1, 0), vis(n + 1, 0), path;

	for (int i = 1; i <= n; i++) {

		int p; cin >> p;

		if (i != p) {

			adj[i].pb(p);

			adj[p].pb(i);

		}

		else root = i;

	}



	for (int i = 1; i <= n; i++) {

		if (n == 1 or (i != root and sz(adj[i]) == 1)) {

			leaf[i] = 1;

		}

	}



	vector<vector<int>> store;



	dfs(root, 0, vis, leaf, path, store, adj);



	cout << sz(store) << "\n";

	for (auto &x : store) {

		cout << sz(x) << "\n";

		for (auto &y : x) {

			cout << y << " ";

		}

		cout << "\n";

	} cout << "\n";

}



