char s[500001], t[500001];

int main()
{
	int n, k;
	scanf("%d%d%s%s", &n, &k, s, t);
	bool common = true;
	long long ans = n;
	k--;
	long long route = 0;
	const char *left, *right;
	long long st = 0, used = 0;
	for (int i = 0; i < n; i++) {
		if (common && s[i] == t[i])
			continue;
		if (common) {
			common = false;
			if (k > 0) {
				ans += n - i;
				k--;
			}
			left = (s[i] < t[i] ? s : t);
			right = (s[i] < t[i] ? t : s);
			continue;
		}
		if (st <= 4e18)
			st *= 2;
		if (left[i] == 'a')
			st++;
		if (right[i] == 'b')
			st++;
		if (k == 0)
			break;
		long long inc = min((long long)k, st - used);
		ans += inc * (n - i);
		k -= inc;
		used += inc;
	}
	cout << ans << '\n';
	return 0;
}

