ll fac[N], inv[N];
ll powmod(ll a, ll b)
{
	a %= mod;
	ll ans = 1;
	while(b)
	{
		if(b&1) ans = ans*a%mod;
		a = a*a%mod;
		b >>= 1;
	}
	return ans;
}
void init(int n)
{
	fac[0] = 1;
	for(int i=1; i<=n; i++) fac[i] = fac[i-1]*i%mod;
	inv[n] = powmod(fac[n], mod-2);
	for(int i=n-1; i>=0; i--) inv[i] = inv[i+1]*(i+1)%mod;
}
ll comb(int a, int b)
{
	if(a<b||b<0||a<0) return 0;
	return fac[a]*inv[b]%mod*inv[a-b]%mod;
}
