int calc ( string s ) {

   string temp = s ;

   char c = s.back() ;

   s.pop_back() ;

   s = c + s ;

   int counter = 1 ;

   while ( s != temp ) {

      counter++ ;

      c = s.back() ;

      s.pop_back() ;

      s = c + s ;

   }

   return counter ;

}



