void NTT(u32*a,int n)
{
	for(int i=0,j=0;i<n;++i)
	{
		if(i<j)swap(a[i],a[j]);
		for(int l=n>>1;~(j^=l)&l;l>>=1);
	}
	for(int i=2;i<=n;i<<=1)
	{
		for(register int j=0,l=i>>1;j<n;j+=i)
