void add(int x,int y)
{
    tot++;
    nex[tot]=head[x];
    head[x]=tot;
    to[tot]=y;
}
int cmp1(int x,int y)
{
    if(!x||!y)
    {
        return x+y;
    }
    return s[x]<s[y]?x:y;
}
int cmp2(int x,int y)
{
    if(!x||!y)
    {
        return x+y;
    }
    return s[x]>s[y]?x:y;
}
void dfs(int x)
{
    size[x]=1;
    s[x]=++num;
    for(int i=head[x];i;i=nex[i])
    {
        d[to[i]]=d[x]+1;
        dfs(to[i]);
        size[x]+=size[to[i]];
        if(size[to[i]]>size[son[x]])
        {
            son[x]=to[i];
        }
    }
}
void dfs2(int x,int tp)
{
    top[x]=tp;
    if(son[x])
    {
        dfs2(son[x],tp);
    }
    for(int i=head[x];i;i=nex[i])
    {
        if(to[i]!=son[x])
        {
            dfs2(to[i],to[i]);
        }
    }
}
int lca(int x,int y)
{
    if(!x||!y)
    {
        return x+y;
    }
    while(top[x]!=top[y])
    {
        if(d[top[x]]<d[top[y]])
        {
            swap(x,y);
        }
        x=f[top[x]];
    }
    return d[x]<d[y]?x:y;
}
int fmin(int l,int r)
{
    if(l>r)
    {
        return 0;
    }
    int len=b[r-l+1];
    return cmp1(mn[l][len],mn[r-(1<<len)+1][len]);
}
int fmax(int l,int r)
{
    if(l>r)
    {
        return 0;
    }
    int len=b[r-l+1];
    return cmp2(mx[l][len],mx[r-(1<<len)+1][len]);
}
