    for(int i=2;i<=n;i++)
    {
        scanf("%d",&f[i]);
        add(f[i],i);
    }
    dfs(1);
    dfs2(1,1);
    for(int i=2;i<=n;i++)
    {
        b[i]=b[i>>1]+1;
    }
    for(int i=1;i<=n;i++)
    {
        mn[i][0]=mx[i][0]=i;
    }
    for(int j=1;(1<<j)<=n;j++)
    {
        for(int i=1;i<=n-(1<<j)+1;i++)
        {
            mn[i][j]=cmp1(mn[i][j-1],mn[i+(1<<(j-1))][j-1]);
            mx[i][j]=cmp2(mx[i][j-1],mx[i+(1<<(j-1))][j-1]);
        }
    }
    while(m--)
    {
        scanf("%d%d",&l,&r);
        int x=fmin(l,r);
        int y=fmax(l,r);
        int lx=fmin(l,x-1);
        int rx=fmin(x+1,r);
        int ans=0;
        int res=0;
        ans=lca(cmp1(lx,rx),y);
        int ly=fmax(l,y-1);
        int ry=fmax(y+1,r);
        res=lca(cmp2(ly,ry),x);
        if(d[ans]>d[res])
        {
            printf("%d %d\n",x,d[ans]);
        }
        else
        {
            printf("%d %d\n",y,d[res]);
        }
    }
}

