using namespace std;

bool solved[51][51];
bool dp[51][51];
long long values[50];
long long desiredNumber;

#define isOn(S, j) (S & (1ll << (j)))
#define setBit(S, j) (S |= (1ll << (j)))
#define clearBit(S, j) (S &= ~(1ll << (j)))

bool solve(long long n, long long k){
	if (solved[n][k])
		return dp[n][k];
	bool solution = false;
	if (k == 1){
		long long sum = 0;
		for (long long i = 0; i < n; i++){
			sum += values[i];
		}
		if ((sum & desiredNumber) == desiredNumber){
			solution = true;
		}
	} else {//k > 1
		long long sum = 0;
		for (long long i = 0; ((i < n - k + 1) && (!solution)); i++){
			sum += values[n - 1 - i];
			if ((sum & desiredNumber) == desiredNumber){
				solution = solve(n - i - 1, k - 1);
			}
		}
	}
	solved[n][k] = true;
	dp[n][k] = solution;
	return dp[n][k];
}

int main(){
	long long n, k;
	cin >> n >> k;
	for (long long i = 0; i < n; i++){
		cin >> values[i];
	}
	long long solution = 0;
	for (long long i = 62; i >= 0; i--){
		setBit(solution, i);
		desiredNumber = solution;
		for (long long i = 0; i <= 50; i++){
			for (long long j = 0; j <= 50; j++){
				solved[i][j] = false;
			}
		}
		if (!solve(n, k)){
			clearBit(solution, i);
		} 
	}
	cout << solution << endl;
}

