void upd(int &x, int y){
  if(x < y) x = y;
}

void solve(char x, char y){
  rep(i, 0, k + 1){
    dp[0][i] = 0;
    tmp[i] = 0;
  }
  rep(i, 1, n + 1){
    if(s[i] == x){
      rep(j, 0, k + 1)  ++tmp[j];
    } else {
      per(j, k, 0)  tmp[j] = tmp[j-1] + 1;
      tmp[0] = 0;
    }
    rep(j, 0, k + 1){
      dp[i][j] = max(dp[i-1][j], tmp[j]);
    }
  }
  rep(i, 0, k + 1){
    dp1[n+1][i] = 0;
    tmp[i] = 0;
  }
  per(i, n, 0){
    if(s[i] == y){
      rep(j, 0, k + 1)  ++tmp[j];
    } else {
      per(j, k, 0)  tmp[j] = tmp[j-1] + 1;
      tmp[0] = 0;
    }
    rep(j, 0, k + 1){
      dp1[i][j] = max(dp1[i+1][j], tmp[j]);
    }
  }

  rep(i, 0, n + 1){
    dp2[i] = -1;
  }

  upd(dp2[dp[n][k]], 0);
  upd(dp2[0], dp1[1][k]);

  rep(i, 1, n){
    rep(j, 0, k + 1){
      upd(dp2[dp[i][j]], dp1[i+1][k-j]);
    }
  }

  if(x == '0'){
    rep(i, 1, n + 1){
      rep(j, 0, n + 1){
        if(dp2[j] == -1)  continue;
        ans[i] = max(ans[i], j * i + dp2[j]);
      }
    }
  } else {
    rep(i, 1, n + 1){
      rep(j, 0, n + 1){
        if(dp2[j] == -1)  continue;
        ans[i] = max(ans[i], j + dp2[j] * i);
      }
    }
  }
}

