namespace Task {



class FenwickTree {

#define up(node) (node | (node + 1))

#define down(node) ((node & (node + 1)) - 1)

public:

  int size_tree;

  vector<llong> tree;



  FenwickTree(){};

  FenwickTree(int init_size) : size_tree(init_size) {

    tree.resize(init_size + 2, 0);

  }



  llong get(int node) const {

    llong ret = 0;

    for (; node >= 0; node = down(node)) {

      ret += tree[node];

    }

    return ret;

  }



  void update(int node, llong value) {

    for (; node <= size_tree; node = up(node)) {

      tree[node] += value;

    }

  }



  void update_range(int l, int r, llong value) {

    update(l, value);

    update(r + 1, -value);

  }



  llong get_range(int l, int r) const { return get(r) - get(l - 1); }

#undef up

#undef down

};



