int solve(int i, vector<int>& dp, vector<int>& line, vector<int>& next, int n){
	if(i > n){
		return 0;
	}
	if(dp[i] != -1) return dp[i];

	int ans = 0;

	// Pick
	ans = max(ans, line[i]+solve(next[i], dp, line, next, n));

	// Not Pick
	ans = max(ans, solve(i+1, dp, line, next, n));

	return dp[i]=ans;
}

