ll expo(ll a, ll b, int mod) {

	if(b == 0) return 1;

	if(b == 1) return a % mod;

	ll ret = expo(a, b>>1, mod);

	ret *= ret;

	if(ret >= mod) ret %= mod;

	if(b & 1) {

		ret *= a;

		if(ret >= mod) ret %= mod;

	}

	return ret;

}



ll inv(ll v, int mod) {

	return expo(v, mod - 2, mod);

}



