inline char gc()
{
    return getchar();
    static char now[1<<16],*S,*T;
    if(S==T) {T=(S=now)+fread(now,1,1<<16,stdin); if(S==T) return EOF;}
    return *S++;
}
inline int read()
{
    int x=0; char ch=gc();
    while(ch<'0'||'9'<ch) ch=gc();
    while('0'<=ch&&ch<='9') x=x*10+ch-'0',ch=gc();
    return x;
}
const int N=4e4+10;
int n,m,k,lenA[N],lenB[N];
int main()
{
    n=read(),m=read(),k=read();
    for(int i=1,pre=1;i<=n;i++)
        if(read()==0) pre=i+1;
        else lenA[i-pre+1]++;
    for(int i=1,pre=1;i<=m;i++)
        if(read()==0) pre=i+1;
        else lenB[i-pre+1]++;
    for(int i=n;i>=1;i--) lenA[i]+=lenA[i+1];
    for(int i=m;i>=1;i--) lenB[i]+=lenB[i+1];
    long long ans=0;
    for(int p=1;p*p<=k;p++)
    {
        if(k%p) continue;
        int q=k/p;
        if(p<=n&&q<=m) ans+=1LL*lenA[p]*lenB[q];
        if(p<=m&&q<=n&&p!=q) ans+=1LL*lenB[p]*lenA[q];
    }
    printf("%lld\n",ans);
    return 0;
}

