bool ok;
bool use[100];
int go[100];
int k,n;
char s[N],a[N],b[N];
void dfs(int now,bool eqa,bool eqb)
{
	if(!eqa && !eqb)
	{
		int id=1;
		for(int i=1;i<=k;++i)
			if(!go[i])
			{
				while(use[id])++id;
				go[i]=id++;
			}
		ok=1;
		return;
	}
	if(now==n+1)
	{
		ok=1;
		int id=1;
		for(int i=1;i<=k;++i)
			if(!go[i])
			{
				while(use[id])++id;
				go[i]=id++;
			}
		return;
	}
	if(go[s[now]])
	{
		int v=go[s[now]];
		if((!eqa||v>=a[now]) && (!eqb||v<=b[now]))
			dfs(now+1,eqa&(v==a[now]),eqb&(v==b[now]));
	}
	else
	{
		for(int i=eqa?(a[now]+1):1;i<(eqb?b[now]:k+1);++i)
			if(!use[i])
			{
				use[i]=1;
				go[s[now]]=i;
				dfs(now+1,0,0);
				return;
			}
		if(!use[a[now]] && (!eqb||a[now]<=b[now]))
		{
			go[s[now]]=a[now];
			use[a[now]]=1;
			dfs(now+1,eqa,eqb&(a[now]==b[now]));
			use[a[now]]=0;
			if(ok)return;
			go[s[now]]=0;
		}
		if(a[now]!=b[now] && !use[b[now]] && (!eqa||a[now]<=b[now]))
		{
			go[s[now]]=b[now];
			use[b[now]]=1;
			dfs(now+1,0,eqb);
			use[b[now]]=0;
			if(ok)return;
			go[s[now]]=0;
		}
	}
}
