#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll mod = 1000000007;

struct Mat{
    ll a, b, c, d;
};

Mat identity = {1,0,0,1};

void mult(Mat& a, Mat& b, Mat &c){
    c.a = a.a * b.a + a.b * b.c;
    c.a %= mod;
    c.b = a.a * b.b + a.b * b.d;
    c.b %= mod;
    c.c = a.c * b.a + a.d * b.c;
    c.c %= mod;
    c.d = a.c * b.b + a.d * b.d;
    c.d %= mod;
}

void fastpow(Mat& a, ll exp, Mat &c){
    if (exp == 0){
        c = identity;
        return;
    }
    Mat d,e;
    fastpow(a,exp/2,d);
    mult(d,d,e);
    if (exp%2){
        mult(a,e,c);
    } else {
        c = e;
    }
}

