int up(int x) {
    int bit = 0;
    while (x) {
        bit++;
        x >>= 1;
    }
    return p - bit >= 0 ? f[p - bit] : 0;
}

bool check(int x) {
    while (1) {
        if (x & 1) {
            x >>= 1;
        } else if ((x & 3) == 0) {
            x >>= 2;
        } else {
            break;
        }
        if (!x) {
            break;
        }
        if (binary_search(a, a + n, x)) {
