    for (int i = 2; i < N; i++) {
        f[i] = f[i - 1] + f[i - 2];
        if (f[i] >= mod) {
            f[i] -= mod;
        }
    }
    for (int i = 1; i < N; i++) {
        add(f[i], f[i - 1]);
