	vector cnt(3, vector<vector<int>>(3));
	for(int i=0; i<n; i++){
		cnt[vorrat.find(a[i])][vorrat.find(b[i])].push_back(i+1);
	}

	// start bei (-, M) oder (-, C)
	// solange (M, -), (C, -), (M, C), (C, M) nicht leer
	// alle: (-, M), (-, C), (M, -), (C, -), (M, C), (C, M), (M, -), (C, -), (-, -)

	auto need = [&](int y){
		return len(cnt[y][0]) or len(cnt[y][3-y]);
	};

	vector<string> v;
	int x, y;
	if(len(cnt[0][1]))
		x=0, y=1;
	else
		x=0, y=2;

	while(need(1) or need(2)){
		assert(len(cnt[x][y]));
		v.push_back("DRIVE "+to_string(*cnt[x][y].rbegin()));
		cnt[x][y].pop_back();

		if(x){
			v.push_back("DROPOFF");
		}
		// brauche ich y?
		if(y){
			if(need(y)){
				v.push_back("PICKUP");
				if(len(cnt[y][3-y])){
					x=y, y=3-y;
				}else{
					x=y, y=0;
				}
			}else{
				x=0, y=3-y;
			}
		}else{
			if(len(cnt[0][1])){
				x=0, y=1;
			}else{
				x=0, y=2;
			}
		}
	}

	cout << len(v) << endl;
	for(auto x:v) cout << x << endl;
}

