ll dist(auto q, auto r) {
    return abs(q.first - r.first) +
           abs(q.second - r.second);
}

void solve() {
    ll n, k, a, b;
    cin >> n >> k >> a >> b;
    pair<ll, ll> x[n + 1];
    for (int i = 1; i <= n; i++) {
        cin >> x[i].first >> x[i].second;
    }
    ll ans = dist(x[a], x[b]);
    ll da = 1e18;
    for (int i = 1; i <= k; i++) {
        da = min(da, dist(x[a], x[i]));
    }
    ll db = 1e18;
    for (int i = 1; i <= k; i++) {
        db = min(db, dist(x[b], x[i]));
    }
    ans = min(ans, da + db);

    cout << ans << '\n';
}

