void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>T;
	while(T--) {
		cin>>N>>K>>L;
		K*=2;
		L*=2;
		ll pos=0,tim=0;
		ll ret=1LL<<30;
		FOR(i,N) {
			cin>>A[i];
			A[i]*=2;
			if(i==0) {
				pos=K;
				tim=A[0];
				ret=tim+(L-pos);
			}
			else {
				if(pos<A[i]-tim) {
					A[i]-=tim;
					assert((A[i]-pos)%2==0);
					tim+=(A[i]-pos)/2;
					pos=(pos+A[i])/2+K;
				}
				else if(A[i]-tim<=pos&&pos<=A[i]+tim) {
					pos+=K;
				}
				else {
					pos=max(pos,A[i]+tim+K);
				}

				if(pos>=L) ret=min(ret,tim);
				else ret=min(ret,tim+L-pos);
			}
		}
		cout<<ret<<endl;
	}
}


