    for(int i=0;i<trees.size();i++){
        int l,r;
        if(i==0){
            l=-1;
        }
        else{
            l = (trees[i]-trees[i-1]-1)/2;
        }
        if(i==trees.size()-1){
            r=-1;
        }
        else{
            r = (trees[i+1]-trees[i])/2;
        }
        lims.push_back({l,r});
