        if(l!=0){
            vals.push({i,{-1,1}});
        }
        if(r!=0){
            vals.push({i,{1,1}});
        }
    }
    // cout<<"---------------"<<endl;
    vector<int> ans;
    ll tally = 0;
    for(int i=0;i<ppl;i++){
