inline bool chk() {
    queue <int> q;
    for (int i = 1; i <= n; i++) {
        vis[i] = 0;
        d[i] = deg[i];
        if (!d[i]) q.push(i);
    }
    for (; !q.empty(); ) {
        int x = q.front(); 
        q.pop();
        vis[x] = 1;
        for (int i = head[x]; i; i = e[i].nxt) {
            int y = e[i].to;
            --d[y];
            if (!d[y]) q.push(y);
        }
    }
    for (int i = 1; i <= n; i++)
        if (!vis[i])
            return 0;
    return 1;
}

inline int solve() {
    queue <int> q;
    for (int i = 1; i <= n; i++) {
        d[i] = deg[i];
        f[i] = 0;
        if (!d[i]) {
            f[i] = 1;
            q.push(i);
        } 
    }
    for (; !q.empty(); ) {
        int x = q.front();
        q.pop();
        for (int i = head[x]; i; i = e[i].nxt) {
            int y = e[i].to;
            --d[y];
            if (y > x) f[y] = max(f[y], f[x]);
            else f[y] = max(f[y], f[x] + 1);
            if (!d[y]) q.push(y);
        }
    }
    int res = 0;
    for (int i = 1; i <= n; i++) res = max(res, f[i]);
    return res;
}

