const int N = 2e5 + 5;
const int inf = 1e9;

int n, a[N], rmq[20][N], l[N], r[N];

void build() {
    for (int i = 1; i <= n; i++)
        rmq[0][i] = i;
    for (int i = 1; i <= 19; i++)
        for (int j = 1; j <= n; j++)
            rmq[i][j] = 0;
    for (int i = 1; i <= 19; i++)
        for (int j = 1; j <= n; j++)
            if (j + (1 << i) - 1 <= n) {
                if (a[rmq[i-1][j]] < a[rmq[i-1][j + (1 << (i-1))]])
                    rmq[i][j] = rmq[i-1][j + (1 << (i-1))];
                else
                    rmq[i][j] = rmq[i-1][j];
            }
}

int get(int l, int r) {
    if (l > r) return -1;
    int k = log2(r - l + 1);
    if (a[rmq[k][l]] < a[rmq[k][r - (1 << k) + 1]])
        return rmq[k][r - (1 << k) + 1];
    else
        return rmq[k][l];
}

struct Rect {
    int width, height;
    Rect(int w = 0, int h = 0): width(w), height(h) {}
};
vector <Rect> rects;

void cal(int l, int r, int height = n) {
    int maxx = get(l+1, r-1);
    if (maxx == -1) return;
    rects.emplace_back(r - l - 1, height - a[maxx]);
    cal(l, maxx, a[maxx]);
    cal(maxx, r, a[maxx]);
}

void solve() {
    cin >> n;

    for (int i = 0; i <= n+1; i++)
        l[i] = r[i] = 0;

    for (int i = 1; i <= n; i++)
        cin >> a[i];

    build();

    stack <int> st; st.push(0);
    for (int i = 1; i <= n; i++) {
        while (st.size() > 1 && a[st.top()] < a[i])
            st.pop();
        l[i] = st.top();
        st.push(i);
    }    
    while (st.size()) st.pop();
    st.push(n + 1);
    for (int i = n; i >= 1; i--) {
        while (st.size() > 1 && a[st.top()] < a[i])
            st.pop();
        r[i] = st.top();
        st.push(i);
    }

    a[0] = a[n+1] = inf;
    rects.clear();
    cal(0, n+1);

    // sort by width
    sort(rects.rbegin(), rects.rend(), [](Rect a, Rect b) {
        return a.width < b.width;
    });

    int k; cin >> k;
    int res = 0;
    for (auto [w, h]: rects) {
        int t = k / w;
        int rows = min(t, h);
        res += rows * (w-1);
        k -= rows * w;
        if (k == 0) break;
        if (rows < h) {
            res += k-1;
            break;
        }
    }

    cout << res << '\n';
}

