#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> PII;

int hot[300005];
int cold[300005];
long long dp[5005][5005];

void solve(){
    int n,k;
    cin>>n>>k;
    vector<int> arr(n+1);
    for(int i=1;i<=n;i++) cin>>arr[i];
    for(int i=0;i<=n;i++) for(int j=0;j<=k;j++) dp[i][j] = 0;

    for(int i=1;i<=k;i++) cin>>cold[i];
    for(int i=1;i<=k;i++) cin>>hot[i];

    for(int i=1;i<=k;i++) dp[0][i] = 1e18;
    for(int i=1;i<=n;i++){
        for(int j=0;j<=k;j++){
            dp[i][j] = dp[i-1][j];
            if(arr[i] == arr[i-1]) dp[i][j] += hot[arr[i]];
            else dp[i][j] += cold[arr[i]];
        }
        long long mini = 1e18;
        for(int j=0;j<=k;j++) mini = min(mini, dp[i-1][j]);
        dp[i][arr[i-1]] = min(dp[i][arr[i-1]], mini+cold[arr[i]]);
        dp[i][arr[i-1]] = min(dp[i][arr[i-1]], dp[i-1][arr[i]]+hot[arr[i]]);
    }

    long long res = 1e18;
    for(int j=0;j<=k;j++) res = min(res, dp[n][j]);
    cout<<res<<endl;
}

int main(){
    ios_base::sync_with_stdio(0);
    int Z;
    cin>>Z;
    while(Z--) solve();
}

