const int N = 2e5 + 10;

const int mod = 1e9 + 7;

int t, n, k;

ll a[N];

ll qpow(ll a, ll b) {

	ll res = 1;

	while (b) {

		if (b & 1)res = res * a % mod;

		a = a * a % mod;

		b >>= 1;

	}

	return res;

}

struct node {

	int id, cnt;

	ll v;

};

bool operator <(const node &x, const node &y) {

	return x.v < y.v;

}

ll f(ll x, ll y) {

	ll v1 = x / y, v2 = x / y + 1;

	ll sz2 = x % y, sz1 = y - sz2;

	ll v3 = x / (y + 1), v4 = x / (y + 1) + 1;

	ll sz4 = x % (y + 1), sz3 = (y + 1) - sz4;

	return sz1 * v1 * v1 + sz2 * v2 * v2 - sz3 * v3 * v3 - sz4 * v4 * v4;

}

int main() {

	ios;

	priority_queue <node> q;

	cin >> n >> k;

	ll res = 0;

	for(int i = 1; i <= n; i++) {

		cin >> a[i];

		res += a[i] * a[i];

		node p = {i, 1, 0};

		p.v = f(a[i], p.cnt);

		q.push(p);

	}

	for(int i = 1; i <= k - n; i++) {

		auto [x, y, z] = q.top();

		q.pop();

		res -= z;

		node p = {x, y, z};

		p.cnt++;

		p.v = f(a[x], p.cnt);

		q.push(p);

	}

	cout << res;

	return 0;

}

