vector<vector<ll>> matmult(vector<vector<ll>> a, vector<vector<ll>> b){
    ll I=a.size(), J=a[0].size(), K=b[0].size();
    vector<vector<ll>> res(I,vector<ll>(K));
    f(i,0,I) f(j,0,J) f(k,0,K) res[i][k] = (res[i][k]+a[i][j]*b[j][k])%mod;
    return res;
}

vector<vector<ll>> matpow(vector<vector<ll>> a, ll n){
    vector<vector<ll>> res(a.size(),vector<ll>(a.size()));
    f(i,0,(ll)a.size()) res[i][i]=1;
    while(n){
        if(n&1) res = matmult(res,a);
        a = matmult(a,a);
        n>>=1;
    }
    return res;
}

