void insert(int x,int id)
{
    int s = 0;
    for(int i = kk;i >= 0;i --)
    {
        int k = (x >> i) & 1;
        if(vis[s][k] != times) ch[s][k] = ++tot;
        else p[ch[s][k]] = times;
        vis[s][k] = times,s = ch[s][k];
    }
    ed[s].push_back(id);
}

int query(int x,int id)
{
    int s = 0,flag = 0;
    for(int i = kk;i >= 0;i --)
    {
        int k = (x >> i) & 1;
        if(vis[s][k] == times && (flag || (p[ch[s][k]] == times))) s = ch[s][k];
        else s = ch[s][!k],flag = 1;
    }
    if(ed[s][0] == id) return ed[s][1];
    return ed[s][0];
}

