using namespace std;

const long long INF = INT_MAX;
const long long MOD = 998244353;

vector<vector<int>> edges;
vector<int> nearest;
vector<bool> vis;
vector<long long> chances;

ll power(ll x, ll y) {
    if (y == 0) return 1;
    ll d = power(x, y / 2);
    if (y % 2 == 0) return (d % MOD * d % MOD) % MOD;
    else return (((x % MOD) * (d % MOD)) % MOD * (d % MOD)) % MOD;
}

int dfs(int x) {
    bool leaf = true;
    int m = INF;
    for (int i : edges[x]) {
        if (!vis[i]) {
            vis[i] = true;
            leaf = false;
            m = min(m, dfs(i));
        }
    }
    if (leaf) {
        nearest[x] = 0;
        return 0;
    }
    nearest[x] = m + 1;
    return m + 1;
}

void dfs2(int x, int lg, long long base) {
    chances[x] = (((nearest[x] * power(lg, MOD - 2)) % MOD) % MOD * base) % MOD;
    for (int i : edges[x]) {
        if (!vis[i]) {
            vis[i] = true;
            if (nearest[i] == nearest[x] - 1) {
                dfs2(i, lg, base);
            }
            else {
                dfs2(i, nearest[i] + 1, chances[x]);
            }
        }
    }
}

