        int right = (n > 1) ? a[n-1] - a[0] : 1;
        if(n ==1){
            right =1;
        }
        int answer = right;
        while(left <= right){
            int mid = left + (right - left) / 2;
            if(is_possible(n, a, mid)){
                answer = mid;
                right = mid -1;
            }
            else{
                left = mid +1;
            }
        }
        cout << answer << "\n";
    }
}

