struct BIT{

	int n, lgn, tr[1000001], val[1000001];

	void init(int x){

		n = x, lgn = 0;

		for (int i = 1;i <= n;i ++) tr[i] = val[i] = 0;

		while (1 << lgn + 1 <= n) lgn ++;

	}

	void update(int p, int x){

		while (p <= n) tr[p] += x, p += lowbit(p);

	}

	int query(int p){

		int ans = 0;

		while (p) ans += tr[p], p -= lowbit(p);

		return ans;

	}

	int kth(int k){

		int ans = 0, sum = 0;

		for (int p = 1 << lgn;p;p >>= 1){

			if (ans + p <= n && sum + tr[ans + p] < k) ans += p, sum += tr[ans];

		}

		return ans + 1;

	}

}st;



