void Dijkstra() {
	rep(i, 1, n)dis[i] = 1ll << 60;
	dis[S = 1] = 0;
	Q.push(mp(0, S));
	while (!Q.empty()) {
		int u = Q.top().second;
		ll Dis = Q.top().first;
		Q.pop();
		if (Dis > dis[u])continue;
		for (int i = head[u]; i; i = e[i].nex) {
			int v = e[i].to;
			if (dis[v] > dis[u] + e[i].w)
				Q.push(mp(dis[v] = dis[u] + e[i].w, v));
		}
	}
}
