  if (n1 + n2 == 0) {
    std::cout << (n3 == 0 || n4 == 0 ? 1 : 0) << '\n';
    return;
  }
  if (std::abs(n1 - n2) > 1) {
    std::cout << "0\n";
    return;
  }

  ll ans = 0;
  if (n1 <= n2) {
    ans += cal(n1 + 1, n2, n3, n4);
  }
  if (n2 <= n1) {
    ans += cal(n1, n2 + 1, n3, n4);
  }

  std::cout << ans % mod << '\n';
}

