using namespace std;

int n, par[200005], sz[200005];

void init()
{
    for (int i = 1; i <= n; i++)
        par[i] = i, sz[i] = 1;
}

int find_parent(int node)
{
    if (par[node] == node)
        return node;

    return par[node] = find_parent(par[node]);
}

void connect(int u, int v)
{
    u = find_parent(u), v = find_parent(v);

    if (sz[u] < sz[v])
        par[u] = v, sz[v] += sz[u];

    else
        par[v] = u, sz[u] += sz[v];
}

int main()
{
    cin.sync_with_stdio(0), cin.tie(0);

    int t, m, k, w, u, v;
    long long ans1, ans2;
    bool ch;
    cin >> t;

    while (t--)
    {
        ans1 = ans2 = 0, ch = true;

        vector <pair <int, pair <int, int>>> edges_less_than_k, edges_more_than_k;

        cin >> n >> m >> k;

        init();

        while (m--)
        {
            cin >> u >> v >> w;

            if (w <= k)
                edges_less_than_k.pb({k-w, {u, v}});

            else
                edges_more_than_k.pb({w-k, {u, v}});
        }

        sort(all(edges_less_than_k)), sort(all(edges_more_than_k));

        for (auto i : edges_less_than_k)
        {
            if (find_parent(i.second.first) != find_parent(i.second.second) && ch)
                ans1 = i.first, ch = false;

            if (find_parent(i.second.first) != find_parent(i.second.second))
                connect(i.second.first, i.second.second);
        }

        if (!ans1 && !ch || edges_more_than_k.empty())
        {
            cout << ans1 << "\n";
            continue;
        }

        ch = true;

        for (auto i : edges_more_than_k)
        {
            if (find_parent(i.second.first) != find_parent(i.second.second) && ch)
                ans1 = 0, ch = false;

            if (find_parent(i.second.first) != find_parent(i.second.second))
                connect(i.second.first, i.second.second), ans1 += i.first;
        }

        if (!ch)
        {
            cout << ans1 << "\n";
            continue;
        }

        cout << min(ans1, 1LL*edges_more_than_k[0].first) << "\n";
    }
    return 0;
}

