		if (tl == tr) {

			t[v] = val;

			return;

		}

		int tm = (tl + tr) / 2;

		if (pos <= tm) up(v * 2, tl, tm, pos, val);

		else up(v * 2 + 1, tm + 1, tr, pos, val);

		t[v] = t[v * 2] + t[v * 2 + 1];

	}

	int ans() {

		return t[1];

	}



};



