int z[2 * maxn];

void getZ(const string &s) {
  for (int i = 1, l = 0, r = -1; i < sz(s); i++) {
    if (i + z[i - l] < r) {
      z[i] = z[i - l];
    } else {
      l = i;
      r = max(r, i);
      while (r < sz(s) && s[r] == s[r - l]) {
        r++;
      }
      z[i] = r - l;
    }
  }
}

int getPos(const string &s, const string &t) {
  getZ(t + "#" + s);
  for (int i = 0; i < sz(s); i++) {
    if (z[sz(t) + 1 + i] >= sz(t)) {
      return i;
    }
  }
  return -1;
}

