const ll MOD = 998244353;



ll quickPow(ll n, ll p, ll k = MOD)

{

    ll ans = 1;

    ll base = n;



    while (p)

    {

        //最后一位为1

        if (p & 1)

        {

            ans *= base;

            ans %= k;

        }

        //去掉一位数

        base *= base;

        base %= k;

        p >>= 1;

    }



    return ans;

}



ll inv(ll x)

{

    return quickPow(x, MOD - 2);

}



