	ver[++ tot] = v;    Next[tot] = head[u];    head[u] = tot;
}

int sta[N];
int cnt[N];

int need[N][2];

void dfs(int u, int fu) {
	if (sta[u] < 2) need[u][sta[u]] ++;
	for (int i = head[u]; i; i = Next[i]) {
		int v = ver[i];
		if (v == fu) continue;
		a[v] = min(a[v], a[u]);
		dfs(v, u);
		need[u][0] += need[v][0];
		need[u][1] += need[v][1];
	}
	cnt[u] = min(need[u][0], need[u][1]);
	need[u][0] -= cnt[u];
	need[u][1] -= cnt[u];
}

