void tarjan(int u){ 
    DFN[u] = LOW[u] = ++tag ;
    gstack.push(u) ;
    instack[u] = true ;
    for(Edge *e = header[u] ; e ; e = e->next){
        if(!DFN[e->v]){
            tarjan(e->v) ;
            LOW[u] = min(LOW[u] , LOW[e->v]) ;
        } else if(instack[e->v]){
            LOW[u] = min(LOW[u] , DFN[e->v]) ;
        }
    }
    if(LOW[u] == DFN[u]){
        instack[u] = false ;
        belg[u] = ++scc ;
        while(gstack.top() != u){
            int v = gstack.top() ; gstack.pop() ;
            belg[v] = scc ; instack[v] = false ;
        }
        gstack.pop() ;
    }
}

