INF = 10 ** 10


def dfs(N, G, F, dest, i, visited, flow):
    visited.add(i)

    if i == dest:
        return flow

    for j in range(N):
        if j in visited or G[i][j] - F[i][j] - G[j][i] + F[j][i] <= 0:
            continue

        this_f = min(flow, G[i][j] - F[i][j] - G[j][i] + F[j][i])
        f = dfs(N, G, F, dest, j, visited, this_f)
        if f > 0:
            F[i][j] += f
            visited.remove(i)
            return f

    visited.remove(i)
    return 0


def maxflow(N, G, F, src, dest):
    flow = 0
    while True:
        f = dfs(N, G, F, dest, src, set(), INF)
        if f == 0:
            break
        flow += f

    return flow


def solve(S, M, A):
    masks = [63] * len(S)
    for i, chars in A:
        mask = 0
        for c in chars:
            mask |= 1 << (ord(c) - ord('a'))
        masks[i] = mask

    maskcnt = [0] * 64
    for m in masks:
        maskcnt[m] += 1

    charcnt = [0] * 6
    for c in S:
        charcnt[ord(c) - ord('a')] += 1

    SOURCE = 0
    SINK = 1
    MASKS = 2
    CHARS = MASKS + 64
    N = CHARS + 6

    G = [[0] * N for _ in range(N)]

    for i in range(64):
        G[SOURCE][MASKS + i] = maskcnt[i]

    for i in range(6):
        G[CHARS + i][SINK] = charcnt[i]

    for m in range(64):
        for i in range(6):
            if m & (1 << i):
                G[MASKS + m][CHARS + i] = INF

    F = [[0] * N for _ in range(N)]
    flow = maxflow(N, G, F, SOURCE, SINK)
    if flow < len(S):
        return None

    ans = []
    k = len(S)
    for i in range(len(S)):
        m = masks[i]
        for c in range(6):
            if not (m & (1 << c)) or G[CHARS + c][SINK] == 0:
                continue
            G[SOURCE][MASKS + m] -= 1
            G[CHARS + c][SINK] -= 1
            k -= 1

            F = [[0] * N for _ in range(N)]
            flow = maxflow(N, G, F, SOURCE, SINK)

            if flow == k:
                ans.append(chr(ord('a') + c))
                break

            G[SOURCE][MASKS + m] += 1
            G[CHARS + c][SINK] += 1
            k += 1

    assert len(ans) == len(S)
    return ''.join(ans)


def main():
    S = input()
    M = int(input())
    A = []
    for _ in range(M):
        ps, chars = input().split(' ')
        p = int(ps)
        p -= 1
        A.append((p, chars))

    res = solve(S, M, A)
    if res is None:
        print('Impossible')
    else:
        print(res)


