def combine(childs):
  if len(childs) == 0:
    return [1], 0

  mlen = max([len(a) for a in childs])
  res = [0 for a in range(mlen)]
  for c in childs:
    for a in range(len(c)):
      res[mlen-a-1] += c[-1-a]

  res.append(1)
  lm = 1
  li = 0
  for a in range(mlen-1, -1, -1):
    if res[a] > lm:
      lm = res[a]
      li = mlen - a
  return res, li

