        else {

            if (x == a[i+1]) {

                dr--;

            }

        }

    }



    a[i] = x;

    k = i + 1;



    dm = dl + dr;

    return (k - 1) *(dl) +(N - k) * (dr) + (k - 1) * (N - k) * (dm); 



}





