void swap(int* arr,int a,int b)
{
	int temp=arr[a];
	arr[a]=arr[b];
	arr[b]=temp;
}
void QuickSort(int* arr,int left,int right)
{
	if(left<right)
	{
		int i=left-1;
		int j=right+1;
		int mid=arr[(left+right)/2];
		while(true)
		{
			while(arr[++i]>mid);
			while(arr[--j]<mid);
			if(i>=j) break;
			swap(arr,i,j);
		}
		QuickSort(arr,left,i-1);
		QuickSort(arr,j+1,right);
	}
}
