void upd(int i, int x, int y){

	auto [i1, j1] = in[i];

	int id = x + y - i1 - j1 + 1;



	if(was[x][y]){

		auto [r,l] = *st[i].lower_bound({id, -1e9});

		assert(l <= id);

		st[i].erase(st[i].find({r,l}));

		if(l <= id){

			int len = r - l + 1;

			ans -= len * (len - 1) /2;



			if(id - 1 >= l){

				st[i].insert({id - 1, l});

				ans += (id - l) * (id - 1 - l)/ 2;

			}

			if(id + 1 <= r){

				st[i].insert({r, id + 1});

				ans += (r - id) * (r - id - 1) / 2;

			}

		}	

	}

	else{

   		auto L = st[i].lower_bound({id - 1, 0});

		int l = id, r = id;



		if(L != st[i].end() and L -> fi == id - 1){

			ans -= (L -> fi - L -> se) * (L -> fi - L -> se + 1) / 2;

			l = L->se;

			st[i].erase(L);

		}	   		

		auto R = st[i].upper_bound({id,0});



		if(R != st[i].end() and R -> se == id + 1){

			int len = R -> fi - R -> se + 1;

			r = R -> fi;

			ans -= (len) * (len - 1) / 2;			

			st[i].erase(R);

		}

		ans += (r - l + 1) * (r - l) / 2;

		st[i].insert({r,l});

	}

}

