using namespace std;
typedef long long ll;
const int size = 1e5+10;
const int inf = 0x3f3f3f3f; 
ll a[size],f[size],sum[size];
ll ver[size],head[size],nxt[size];
int n;
int cnt =0;
bool flag=true;
ll ans =0;
template <typename T> inline void read(T &x){
   x=0;int f=1;char ch=getchar();
   for(;!isdigit(ch);ch=getchar()) if(ch=='-') f=-1;
   for(;isdigit(ch);ch=getchar()) x=(x<<1)+(x<<3)+ch-'0';
   x*=f;
}
inline void addedge(int u,int v){
	ver[++cnt]=v,nxt[cnt]=head[u],head[u]=cnt;
}
queue <int> q;
inline void bfs(int s){
	q.push(s);
	while(!q.empty()){
		int u=q.front();q.pop();
		if(sum[u]!=-1){               //奇数层已经给定sum 
			for(register int i=head[u];i;i=nxt[i]){
				int v=ver[i];
				if(v!=f[u]) q.push(v);
			}
		}else{                        //偶数层 
			ll minn=inf;
			for(register int i=head[u];i;i=nxt[i]){
				int v=ver[i];
				if(v!=f[u]) minn = min(sum[v],minn);
			}
			if(minn==inf) a[u]=0;     //没有儿子 
			else{
				a[u] = minn-sum[f[u]];  //附上最大可能值 
				for(register int i=head[u];i;i=nxt[i]){
					int v=ver[i];
					if(v==f[u]) continue;
					a[v] = sum[v]-minn;
					q.push(v);
				} 
			}
		}
	}
}
