const int Max_N(100005), Mod(998244353);

int N, M, K, S;
std::vector<int> s[105];
int dist[105][Max_N];
int ecnt(1), first[Max_N * 2], Next[Max_N * 2], To[Max_N * 2]; 

void bfs(const int k)
{
	for (int i(1); i <= N; ++i)
		dist[k][i] = 1 << 30;
	static int queue[Max_N];
	int *cur1(queue), *cur2(queue);
	for (int i(0); i != s[k].size(); ++i)
		dist[k][*++cur2 = s[k][i]] = 0;
	while (cur1 != cur2)
	{
		int v(*++cur1);
		for (int e(first[v]); e; e = Next[e])
			if (dist[k][To[e]] == (1 << 30))
				dist[k][To[e]] = dist[k][v] + 1, *++cur2 = To[e];
	}
}

int main(int argc, char **argv)
{
	IO >> N >> M >> K >> S;
	for (int i(1), a; i <= N; ++i)
		IO >> a, s[a].push_back(i);
	for (int i(0), v, w; i != M; ++i)
	{
		IO >> v >> w;
		Next[ecnt] = first[v], To[ecnt] = w, first[v] = ecnt++;
		Next[ecnt] = first[w], To[ecnt] = v, first[w] = ecnt++;
	}

	for (int i(1); i <= K; ++i)
		bfs(i);

	for (int i(1); i <= N; ++i)
	{
		static int tmp[Max_N];
		for (int k(1); k <= K; ++k)
			tmp[k] = dist[k][i];
		std::nth_element(tmp + 1, tmp + S, tmp + 1 + K);
		int Ans(0);
		for (int k(1); k <= S; ++k)
			Ans += tmp[k];
		printf("%d ", Ans);
	}

	return 0;
}

#include <bits/stdc++.h>
using namespace std;


const int maxn = 2e6 + 7;

int n, timestamp;
int anc[maxn], o[maxn];
int p[maxn], L[maxn], R[maxn];
int nxt[maxn], v[maxn], head[maxn];
int r[maxn];
bool vis[maxn];

void update(int x, int value) {
	if (!x) return ;
	while (x <= n) {
		r[x] += value;
		x += x & -x;
	}
}

int query(int x) {
	int rt = 0;
	if (x == 0) return 0;
	while (x) {
		rt += r[x];
		x -= x & -x;
	}
	return rt;
}

void insert(int a, int b) {
	static int N = 0;
	N++;
	nxt[N] = head[a];
	head[a] = N;
	v[N] = b;
}

int main() {
//	freopen("input.txt", "r", stdin);
	int k;
	scanf("%d%d", &n, &k);
	for (int i = 1; i < n; i++) {
		int u, v;
		scanf("%d%d", &u, &v);
		insert(u, v);
		insert(v, u);
	}

	for (int i = 1; i <= n; i++) p[i] = head[i];

	int h = 0;
	o[h] = n;
	L[n] = ++timestamp;
	while (h >= 0) {
		int u = o[h];
		if (!p[u]) {
			h--;
			R[u] = timestamp;
			continue;
		}
		int tar = v[ p[u] ]; p[u] = nxt[ p[u] ];
		if (tar == anc[u]) continue;
		anc[tar] = u;
		o[++h] = tar;
		L[tar] = ++timestamp;
	}

	for (int i = 1; i < n; i++) {
		update(R[i] + 1, -1);
		update(L[i], 1);
	}

	vis[n] = true;	
	// calced[n] = true;

	int rest = n - k - 1;
	for (int i = n - 1; i >= 1; i--) {
		if (vis[i]) continue;
		if (query(L[i]) > rest) continue;

		int u = i;
		while (!vis[u]) {
			vis[u] = true;
			rest--;
			update(R[u] + 1, 1);
			update(L[u], -1);
			u = anc[u];
		}
	}
	for (int i = 1; i <= n; i++) 
		if (!vis[i]) printf("%d ", i);
	puts("");
	return 0;
}

