int find(int x){
    if(ft[x] == x){
        return x;
    }

    return ft[x] = find(ft[x]);
}

void join(int u, int v, ll w){
    int x = find(u);
    int y = find(v);

    if(x != y){
        if(x < y){
            ft[y] = x;
        }else{
            ft[x] = y;
        }

        total_cost += w;
    }
}

