const int Inf = 2e9;
const int N = 200005;
int T, n, m, k, ans, ans1, a[N], b[N], f[N], g[N];

inline int read()
{
	char c = getchar();
	int ans = 0;
	bool f = 1; 
	while (c < 48 || c > 57)
	{
		if (c == '-') f = 0;
		c = getchar();
	}
	while (c >= 48 && c <= 57) ans = (ans << 3) + (ans << 1) + (c ^ 48), c = getchar();
	return f ? ans : -ans;
}

inline void write(int x)
{
	if (x < 0) putchar('-'), x = -x;
	int num = 0;
	char sc[15];
	if (!x) sc[num = 1] = 48;
	while (x) sc[++num] = x % 10 + 48, x /= 10;
	while (num) putchar(sc[num--]);
	putchar('\n');
}

int main()
{
	T = read();
	while (T--)
	{
		n = read(), m = read(), k = ans = ans1 = 0;
		for (Re i = 1; i <= n; ++i)
		{
			a[i] = read();
			if (a[i] < 0) k = i;
		}
		for (Re i = 1; i <= m; ++i) b[i] = read();
		a[0] = -Inf, a[n + 1] = Inf;
		for (Re i = 0; i <= n + 1; ++i) f[i] = g[i] = 0;
		for (Re i = 1, j = 1; i <= k; ++i)
		{
			while (j < m && b[j + 1] <= a[i]) ++j;
			if (a[i] == b[j]) f[i] = f[i - 1] + 1;
			else f[i] = f[i - 1];
			if (f[i] > ans) ans = f[i];
		}
		for (Re i = n, j = m; i > k; --i)
		{
			while (j > 1 && b[j - 1] >= a[i]) --j;
			if (a[i] == b[j]) g[i] = g[i + 1] + 1;
			else g[i] = g[i + 1];
			if (g[i] > ans1) ans1 = g[i];
		}
		for (Re i = 1, l = 1, r = 0; i <= k; ++i)
		{
			while (l <= m && b[l] < a[i - 1] + 1) ++l;
			if (l > m) break;
			while (l <= m && b[l] <= a[i])
			{
				while (r < m && b[r + 1] <= b[l] + k - i) ++r;
				if (l <= r && f[i - 1] + r - l + 1 > ans) ans = f[i - 1] + r - l + 1;
				++l;
			}
		}
		for (Re i = n, r = m, l = m + 1; i > k; --i)
		{
			while (r && b[r] > a[i + 1] - 1) --r;
			if (!r) break;
			while (r && b[r] >= a[i])
			{
				while (l > 1 && b[l - 1] >= b[r] - i + k + 1) --l;
				if (l <= r && g[i + 1] + r - l + 1 > ans1) ans1 = g[i + 1] + r - l + 1;
				--r;
			}
		}
		ans += ans1;
		write(ans);
	}
	return 0;
}

