				} else {

					ans = min((c[2] + c[4]) * -x, c[3] * -x);

				}

			}

		} else {

			// 0

			if(x > 0 && y > 0 && x < y) {

				ll d0 = x, d1 = y - x;

				ll tmp0 = min(c[0], c[1] + c[5]) * d0;

				ll tmp1 = min(c[1], c[0] + c[2]) * d1;

				ans = tmp0 + tmp1;

			}

			// 1

			if(x < 0 && y > 0) {

				ll d1 = y, d2 = -x;

				ll tmp0 = min(c[1], c[0] + c[2]) * d1;

				ll tmp1 = min(c[2], c[1] + c[3]) * d2;

				ans = tmp0 + tmp1;

			}

			// 2

			if(x < 0 && y < 0 && x < y) {

				ll d2 = y - x, d3 = -y;

				ll tmp0 = min(c[2], c[1] + c[3]) * d2;

				ll tmp1 = min(c[3], c[2] + c[4]) * d3;

				ans = tmp0 + tmp1;

			}

			// 3

			if(x < 0 && y < 0 && x > y) {

				ll d3 = -x, d4 = x - y;

				ll tmp0 = min(c[3], c[2] + c[4]) * d3;

				ll tmp1 = min(c[4], c[3] + c[5]) * d4;

				ans = tmp0 + tmp1;

			}

			// 4

			if(x > 0 && y < 0) {

				ll d4 = -y, d5 = x;

				ll tmp0 = min(c[4], c[3] + c[5]) * d4;

				ll tmp1 = min(c[5], c[4] + c[0]) * d5;

				ans = tmp0 + tmp1;

			}

			// 5

			if(x > 0 && y > 0 && x > y) {

				ll d5 = x - y, d0 = y;

				ll tmp0 = min(c[5], c[4] + c[0]) * d5;

				ll tmp1 = min(c[0], c[1] + c[5]) * d0;

				ans = tmp0 + tmp1;

			}

		}

		assert(ans != -1);

		cout << ans << '\n';

	}

    return 0;

}

