        {
            int ways=mul(2,C(cnt[i],2));

            for(int j=0;j<curr.size();j++)
            {
                int zz=mul(curr[j],ways);

                int prob=mul(fact[n-j-2],inv_fact[n]);

                prob=mul(prob,zz);

                res=add(res,prob);
            }
        }

        vector<int> now;now.pb(1);now.pb(cnt[i]);

        curr=mult(curr,now);
    }

    cout<<res<<endl;

