node combine(const node &n1,const node &n2){
	//no swaps allowed, only combine by copies.
	node c;
	for(int i=0;i<41;i++){
			for(int j = 0;j<i;j++){
					c.inv += n1.arr[i]*n2.arr[j];
				}	
		}
	for(int i=0;i<41;i++)c.arr[i] = n1.arr[i]+n2.arr[i];
	return c;
}

void build(int v, int tl, int tr,vector<ll> &a){
	if(tl == tr){
		t[v].arr[a[tl]] = 0;
		t[v].arr[a[tl]]++;
	}
	else{
		int tm = (tl+tr)>>1;
		build(2*v,tl,tm,a);
		build(2*v+1,tm+1,tr,a);
		t[v] = combine(t[2*v],t[2*v+1]);
	}
}

vector<ll> query(int v, int tl, int tr, int l, int r,vector<ll> &a){
	if(l > r){
		vector<ll> a(41,0);
		return a;
	}
	if(tl == l && tr == r){
		vector<ll> ar(41);
		for(int i=0;i<41;i++)ar[i] = t[v].arr[i];
		ans += t[v].inv;
		return ar;
	}
	else{
		int tm = (tl+tr)>>1;
		vector<ll> a1 =  query(2*v,tl,tm,l,min(r,tm),a);
		vector<ll> a2 = query(2*v+1,tm+1,tr,max(l,tm+1),r,a);

		for(int i=0;i<41;i++){
			for(int j = 0;j<i;j++){
					ans += a1[i]*a2[j];
				}	
		}
		for(int i=0;i<41;i++){
			a1[i]+=a2[i];
		}
		return a1;
	}
}
void upd(int v, int tl, int tr, ll pos, ll val){
	if(tl == tr){
		for(int i=0;i<41;i++){
			t[v].arr[i] = 0;
		}
		t[v].arr[val]++;
		return;
	}
	else{
		int tm = (tl+tr)>>1;
		if(pos<=tm)upd(2*v,tl,tm,pos,val);
		else upd(2*v+1,tm+1,tr,pos,val);
		t[v] = combine(t[2*v],t[2*v+1]);
	}
}
