        if (make) {
            bool xd = (rev < norm);
            rep(j, 0, m) {
                char a = perm[i%2][(j+xd)%2];
                M2[i][j] = a;
            }
        }
    }

    return ans;
}

int fillCol(char perm[2][2], bool make) {
    int ans = 0;

    rep(i, 0, m) {
        int norm = 0, rev = 0;

        rep(j, 0, n) {
            char a = perm[i%2][j%2];
            char b = perm[i%2][(j+1)%2];
            if (a != M[j][i]) norm++;
            if (b != M[j][i]) rev++;
