bool isprime[100000];
vector<long long> p;
void init(){
	isprime[0] = true;
	isprime[1] = true;
	for(long long i = 2 ; i <= 99999 ; i++){
		if(isprime[i]) continue;
		p.push_back(i);
		for(long long j = 2 ; j * i <= 99999 ; j++) isprime[i*j] = true;
	}
}

long long mi;
void cal(long long left, long long right, vector<long long> &div, long long acc, int num, int cc) {
	if(num == div.size()) {
		if(acc == 1) return;
		if(cc%2==1)
			mi += right/acc - left/acc;
		else mi -= right/acc - left/acc;
		return;
	}
	cal(left,right,div,acc,num+1, cc);
	cal(left,right,div,acc*div[num], num+1, cc+1);

}

int main(){
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	init();
	int t;
	cin >> t;
	while(t--){
		long long a,m;
		cin >> a >> m;
		long long g = gcd(a,m);
		long long left = a/g - 1;
		long long right = m/g + a/g -1;
		long long ans = right - left;
		// cout << "ans " << ans << endl;
		vector<long long> div;
		long long k  = m/g;

		for(int i = 0 ; i < p.size() ; i++){
			if(k % p[i] == 0){
				div.push_back(p[i]);
				while(k % p[i] == 0){
					k /= p[i];
				}
			}
		}
		if( k > 1) div.push_back(k);
		mi = 0;
		cal(left, right, div, 1, 0, 0);
		cout << ans - mi << endl;


	}

	return 0;
}

