int fastpow(ll b,ll p, ll mod)
{

    if (p==0)return 1;
    if(p==1)return b;
    ll x= fastpow(b,p/2,mod)%MOD;
    x=(x%MOD*x%MOD)%mod;
    if(p%2)return (x%MOD*b%MOD)%mod;
    else return x%mod;

}

