void move1step(int &a,int &b,int q)
{

    int nex=a-b*q;
    a=b;
    b=nex;

}

int eculidean(int a,int b,int &x0,int &y0)
{

    int r0=a,r1=b;
    int x1=0,y1=1;
    x0=1,y0=0;
    while(r1){
        int q=r0/r1;
        move1step(r0,r1,q);
        move1step(x0,x1,q);
        move1step(y0,y1,q);
    }
    return r0;

}

int modinvgeneral(int c,ll mod){
    int x,y;
    if(eculidean(c,mod,x,y)==1)
    {
        return (x+mod)%mod;}
    else return -1;

}
