int par[nmax], asc[nmax], nxt[nmax];
int n;

int findPar (int x) {
    if (par[x] == 0) return x;
    par[x] = findPar(par[x]);
    return par[x];
}

int findAsc (int x) {
    if (asc[x] == 0) return x;
    asc[x] = findAsc(asc[x]);
    return asc[x];
}

int main () {
    read(n); int i;
    FOR(i, 1, n) {
        nxt[i] = 0;
        asc[i] = 0;
        par[i] = 0;
    }
    int u, v, a, b;
    FORK(i, 1, n) {
        read(a); read(b);
        if (par[a] == 0) {
            if (par[b] == 0) {
                u = findAsc(a);
                nxt[u] = b; asc[u] = b;
                par[b] = findPar(a);
            }
            else {
                u = findAsc(b);
                nxt[u] = a; asc[u] = a;
                par[a] = findPar(b);
            }
        }
        else {
            if (par[b] == 0) {
                u = findAsc(a);
                nxt[u] = b; asc[u] = b;
                par[b] = findPar(a);
            }
            else {
                u = findAsc(a);
                v = findPar(b);
                nxt[u] = v; asc[u] = v;
                par[v] = findPar(a);
            }
        }
    }
    int c;
    FOR(i, 1, n)
        if (par[i] == 0) {
            c = i; break;
        }
    FOR(i, 1, n) {
        write(c); putchar(' ');
        c = nxt[c];
    }
	return 0;
