const int N = 500010;
struct Node {
	int l, r;
} ans[N];
int en, head[N], cnt[N], sz[N];
struct Edge {
	int to, nxt;
} e[N << 1];

inline void add(int x, int y)
{
	e[++en].to = y;
	e[en].nxt = head[x];
	head[x] = en;
}

inline void dfs(int x, int fa)
{
	sz[x] = 1;
	for (register int i = head[x]; i; i = e[i].nxt) {
		if (e[i].to == fa) continue;
		++cnt[x];
		dfs(e[i].to, x);
		sz[x] += sz[e[i].to];
	}
}

inline int ret(int x, int fa, int l, int r)
{
	register int tot = 0, ls = l;
	for (register int i = head[x]; i; i = e[i].nxt) {
		if (e[i].to == fa) continue;
		++tot;
		ans[e[i].to].l = ls - cnt[e[i].to] - 1, ans[e[i].to].r = l + tot;
		ls = ret(e[i].to, x, ls - cnt[e[i].to] - 1, l + tot);
	}
	return ls;
}


