const ll N = 1e6 + 6, M = 1e9 + 7;
struct DSU
{
    int parts;
    vector<int> rt, sz;

    DSU(int n)
    {
        rt.resize(n + 1);
        sz.resize(n + 1, 1);
        iota(rt.begin(), rt.end(), 0);
        parts = n;
    }

    int root(int k)
    {
        while (k != rt[k])
            k = rt[k] = rt[rt[k]];
        return k;
    }

    void U(int u, int v)
    {
        int r1 = root(u), r2 = root(v);
        if (r1 == r2)
            return;
        parts--;
        if (sz[r1] > sz[r2])
            swap(r1, r2);
        sz[r2] += sz[r1];
        sz[r1] = 0;
        rt[r1] = rt[r2];
    }
};
int main()
{
    ios::sync_with_stdio(false), cin.tie(nullptr);
    ll n, m, e = 0;
    cin >> n >> m;
    DSU d(n);
    multiset<ll> s;
    while (m--)
    {
        ll x, y;
        cin >> x >> y;
        x = d.root(x);
        y = d.root(y);
        if (x == y)
            e++;
        else
        {
            if (d.sz[x] > 1)
                s.erase(s.find(d.sz[x]));
            if (d.sz[y] > 1)
                s.erase(s.find(d.sz[y]));
            d.U(x, y);
            x = d.root(x);
            s.insert(d.sz[x]);
        }
        auto it = s.rbegin();
        ll ans = 0, i = 0;
        for (; i <= e && it != s.rend(); i++, it++)
            ans += *it;
        cout << ans + e - i << '\n';
    }
}

