template<class T> struct BIT {
    int n;
    vector<T> bit;

    BIT(int sz) { bit.resize(n = sz + 7); }

    void upd(int i, T x) { 
        for(i++; i < n; i += i & -i) bit[i] += x;
    }

    T query(int i) {
        int ret = 0;
        for(i++; i > 0; i -= i & -i) ret += bit[i];
        return ret;
    }

    T query(int l, int r) { return (l > r ? 0 : query(r) - query(l - 1)); };
};

int main() {
