void f(int s,int e,int bit,int now)
{
    //printf("%d %d %d %d\n",s,e,bit,now);
    if(bit<0)
    {
        int mmax=0;
        for(int i=s;i<=e;i++) mmax=max(mmax,now^b[i]);
