        int one=-1;
        for(int i=s;i<=e;i++)
        {
            if((1<<bit)&b[i])
            {
                one=i;
                break;
            }
        }
        if(one==-1) f(s,e,bit-1,now);
        else if(one==s) f(s,e,bit-1,now|(1<<bit));
        else
        {
            f(s,one-1,bit-1,now|(1<<bit));
            f(one,e,bit-1,now);
        }
    }
}

