void Upd(int v)
{
	tmx[v][0] = max(tmx[v * 2][0], tmx[v * 2 + 1][0]);
	tmn[v][0] = min(tmn[v * 2][0], tmn[v * 2 + 1][0]);
	tmx[v][1] = max(tmx[v * 2][1], tmx[v * 2 + 1][1]);
	tmn[v][1] = min(tmn[v * 2][1], tmn[v * 2 + 1][1]);
	tans[v] = max(tans[v * 2], tans[v * 2 + 1]);
	tans[v] = max(tans[v], tmx[v * 2 + 1][0] - tmn[v * 2][0]);
	tans[v] = max(tans[v], tmx[v * 2 + 1][1] - tmn[v * 2][1]);
}

void build(int v, int tl, int tr)
{
	if(tl == tr)
	{
		tans[v] = 0;
		tmn[v][0] = a[tl]-tl;
		tmx[v][0] = a[tl]-tl;
		tmn[v][1] = -a[tl]-tl;
		tmx[v][1] = -a[tl]-tl;
		return;
	}
	build(v * 2, tl, (tl + tr) / 2);
	build(v * 2 + 1, (tl + tr) / 2 + 1, tr);
	Upd(v);
}

void upd(int v, int tl, int tr, int pos)
{
	if(pos < tl || tr < pos) return;
	if(tl == tr)
	{
		tans[v] = 0;
		tmn[v][0] = a[tl]-tl;
		tmx[v][0] = a[tl]-tl;
		tmn[v][1] = -a[tl]-tl;
		tmx[v][1] = -a[tl]-tl;
		return;
	}
	upd(v * 2, tl, (tl + tr) / 2, pos);
	upd(v * 2 + 1, (tl + tr) / 2 + 1, tr, pos);
	Upd(v);
}

