int bin_pow(int a, int n) {
	int res = 1;
	for (int s = a; n; s = (s * s) % MOD, n >>= 1ll) {
		if (n & 1ll)
			res = (res * s) % MOD;
	}
	return res;
}

int back_mod(int a) {
	return bin_pow(a, MOD - 2);
