void add(int type, int x, int y)
{
	tot++;
	edge[tot].st = x;
	edge[tot].ed = y;
	edge[tot].nxt = head[x];
	edge[tot].type = type;
	head[x] = tot;
}
bool dfs(int x, int now)
{
	dir[x] = now;
	for (int i = head[x]; i; i = edge[i].nxt)
	{
		int y = edge[i].ed;
		if (dir[y] == now) return false;
		if (dir[y] != 0) continue;
		if (!dfs(y, 3 - now)) return false;
	}
	return true;
}
