const int mod = 998244353;
int mult(int a, int b) {
    return (1LL * a * b) % mod;
}
int sum(int a, int b) {
    int s = a + b;
    if (s >= mod) s -= mod;
    return s;
}
int lp[maxN];
vector<pair<int,pair<int,int>>> g[maxN];
int mx[maxN];
int coef[maxN];
void add(int x, int d, bool calc=false) {
    while (x > 1) {
        int p = lp[x];
        while (x % p == 0) {
            x /= p;
            cur_sum[p] += d;
        }
//        assert(1 <= p && p <= n);
        if (calc) {
            mx[p] = max(mx[p], cur_sum[p]);
        }
    }
}
void dfs(int v, int p) {
    for (auto& it : g[v]) {
        int u = it.first;
        int x = it.second.first;
        int y = it.second.second;
        if (u == p) continue;
        coef[u] = coef[v];
        coef[u] = mult(coef[u], y);
        coef[u] = mult(coef[u], inv[x]);
        add(y, -1);
        add(x, +1, true);
        dfs(u, v);
        add(y, +1);
        add(x, -1);
    }
}
