def solve():
	n, m = map(int, input().split())
	g = [[] for i in range(n+1)]
	for i in range(m):
		u, v = map(int, input().split())
		g[u].append([v,i])
		g[v].append([u,i])
	P = [-1]*(n+1)
	I = [0]*(n+1)
	st = []
	D = [0]*(n+1)
	up = [0]*(n+1)
	W = [0]*(n+1)
	F = [False]*(n+1)
	for i in range(1, n+1):
		if P[i] >= 0:
			continue
		P[i] = 0
		D[i] = 0
		st.append(i)
		while len(st) > 0:
			x = st[-1]
			p = P[x]
			if p == 0 and I[x] == 1 and len(g[x]) > 1:
				v, w = g[x][I[x]]
				if P[v] < 0:
					F[x] = True
			while I[x] < len(g[x]):
				v, w = g[x][I[x]]
				I[x] += 1
				if P[v] < 0:
					D[v] = D[x] + 1
					up[v] = D[v]
					P[v] = x
					W[v] = w
					st.append(v)
					break
				elif v != p and D[v] < D[x]:
					up[x] = min(up[x], up[v])
			else:
				if p > 0:
					up[p] = min(up[p], up[x])
				if p != 0 and up[x] >= D[x]:
					F[x] = True
				st.pop()
	P = [-1]*(n+1)
	I = [0]*(n+1)
	C = [0]*(n+1)
	E = []
	for i in range(1, n+1):
		if P[i] >= 0:
			continue
		P[i] = 0
		if not F[i]:
			C[i] = len(E)
			E.append([])
		st.append(i)
		while len(st) > 0:
			x = st[-1]
			p = P[x]
			while I[x] < len(g[x]):
				v, w = g[x][I[x]]
				I[x] += 1
				if P[v] < 0:
					if F[x]:
						C[v] = len(E)
						E.append([])
					else:
						C[v] = C[x]
					E[C[v]].append((x, v, w))
					P[v] = x
					st.append(v)
					break
				elif v != p and D[v] < D[x]:
					E[C[x]].append((x, v, w))
			else:
				st.pop()
	r = []
	for e in E:
		d = dict()
		for u, v, w in e:
			d[u] = d.get(u,0)+1
			d[v] = d.get(v,0)+1
		for u in d:
			if d[u] != 2:
				break
		else:
			for u, v, w in e:
				r.append(w)
	r.sort()
	print(len(r))
	print(' '.join(str(i+1) for i in r))

