int main() {
	int i,j,k,x,y;
	scanf("%d",&n);
	for(i=1;i<=n;i++) scanf("%d",&val[i]);
	for(i=1;i<n;i++) {
		scanf("%d%d",&x,&y);
		AE(x,y);AE(y,x);
	}
	DC(FindRoot(1,n),n);
	for(i=1;i<N;i++) {
		if(ans[i]) {
			cout<<i<<' '<<ans[i]<<endl;
		}
	}
}

