struct TS {
    vector<bool> used;
    vector<int> order, comp;
    vector<bool> assignment;
    void dfs1(int v) {
        used[v] = 1;
        for (int u : G[v]) if (!used[u]) dfs1(u);
        order.push_back(v);
    }
    void dfs2(int v, int cl) {
        comp[v] = cl;
        for (int u : TG[v]) if (comp[u] == -1) dfs2(u, cl);
    }
    bool solve_2SAT(int n) {
        used.assign(n, false); order.clear();
        REP(i,n) if (!used[i]) dfs1(i);
        comp.assign(n, -1);
        for (int i = 0, j = 0; i < n; ++i) {
            int v = order[n - i - 1];
            if (comp[v] == -1) dfs2(v, j++);
        }
        assignment.assign(n >> 1, false);
        for (int i = 0; i < n; i += 2) {
            if (comp[i] == comp[i + 1]) return false;
            assignment[i>>1] = comp[i] > comp[i + 1];
        }
        return true;
    }
    void add_edge(int v1, int v2){
        G[v1].push_back(v2);
        TG[v2].push_back(v1);
    }
    void add_disjunction(int v1, int v2){
        add_edge(v1 ^ 1, v2);
        add_edge(v2 ^ 1, v1);
    }
};
