/*

    HINT : 

        1. if Sorted >> Binary Search
            upper_bound 
            lower_bound
        2. if we want to find range >> Sliding Window
            Use Two Loops rather than 2 Variables(Start, end);
            Otherwise you will get confused
        3. Vector are Always Better Then Unordered Map
        4. Set stores data in sorted form (and you can also apply
          binary_search on them)
*/
ll Power(ll a, ll b){
    if(b == 0){
        return 1;
    }
    if(b%2 == 0){
        a = (a * a)%MOD;
        b = b/2;
        return Power(a, b);
    }else{
        return (Power(a, b - 1) * a)%MOD;
    }
}
